UPDATE S09W007T GUDW 
  SET
    GUDW.KSIKEKKATORIKOMIFLG   = '2' 
  , GUDW.APTORIKOMIDD          = NULL
  , GUDW.KOSHAAPKIHONCD        = #{entity.koshaapkihoncd,jdbcType=VARCHAR}
  , GUDW.KOSHASHOPCD           = #{entity.koshashopcd,jdbcType=VARCHAR}
  , GUDW.KOSHACD               = #{entity.koshacd,jdbcType=VARCHAR}
  , GUDW.KSHNSYSTMYMD          = #{entity.kshnsystmymd,jdbcType=VARCHAR}
  , GUDW.KSHNSYSTMJIKAN        = #{entity.kshnsystmjikan,jdbcType=VARCHAR}
  , GUDW.KSHNUNYOYMD           = #{entity.kshnunyoymd,jdbcType=VARCHAR}
  , GUDW.KSHNIPADRSE           = #{entity.kshnipadrse,jdbcType=VARCHAR}
  , GUDW.KSHNPGMID             = #{entity.kshnpgmid,jdbcType=VARCHAR}
WHERE
      GUDW.APKIHONCD           = #{entity.apkihoncd,jdbcType=VARCHAR}
  AND GUDW.SHOPCD              = #{entity.shopcd,jdbcType=VARCHAR}
  AND GUDW.SHIMEDYDM           = #{entity.shimedydm,jdbcType=VARCHAR}
  AND GUDW.KSIKKNCD            = #{entity.ksikkncd,jdbcType=VARCHAR}
  AND GUDW.KSIKEKKATORIKOMIFLG = '3' 
  AND EXISTS ( 
    SELECT
        KH.APKIHONCD 
    FROM
        S09T001T KH 
    WHERE
            KH.APKIHONCD     = GUDW.APKIHONCD 
        AND KH.SHOPCD        = GUDW.SHOPCD 
        AND KH.SHIMEDYDM     = GUDW.SHIMEDYDM 
        AND KH.KSIKKNCD      = GUDW.KSIKKNCD 
        AND KH.JOTAI         = '3'
        AND KH.KSIKEKKA      IS NOT NULL
  )

